#region Purpose
// Contract for fetching the signed-in user's display profile (alias, prefs, avatar), with a mock for backend-less demos.
#endregion

#region Design
// The Query has no properties — identity comes from the auth context, which is why the route says Users/Current.
// The empty Validator satisfies the convention that every request ships one, keeping source-gen and test
// patterns uniform across contracts.
// Guard clauses in the Response constructor make an empty profile unrepresentable; Avatar is a
// non-empty string (data URI) so the UI never receives a blank image source.
// Wire names (task 148 D2 / 205): Alias maps from domain DisplayName (chrome-facing name stays Alias);
// Email is optional progressive profile; Language/Region/Theme/Notifications mirror the Profile
// aggregate; Avatar is not domain/EF. Response implements IProfileDetails so the Profile page form
// binds the same shape UpdateProfile submits.
// Mock Avatar (task 149): precomputed Multiavatar data URI for seed "GetProfile.Mock" so
// web-contracts does not reference TimeWarp.Multiavatar; regenerate offline if the package
// output shape changes.
// [EndpointAllowAnonymous] (task 110 / 148 D3): the handler is deliberately dual-mode — an
// anonymous caller gets the contract's mock response so the demo works with no sign-in, and an
// authenticated caller (ICurrentPrincipalAccessor resolves a current principal — task 150) gets
// store-backed create-if-missing profile data. Requiring auth at the endpoint would break the
// anonymous demo path. Page gate remains PermissionIds.ProfileRead.
#endregion

namespace TimeWarp.Architecture.Features.Profiles;

[ApiEndpoint]
[EndpointAllowAnonymous("Handler is deliberately dual-mode (anonymous demo response vs store-backed authenticated response); requiring auth would break the anonymous demo path. Page stays PermissionIds.ProfileRead (task 148 D3 / 182-003).")]
public static partial class GetProfile
{
  [ApiRoute(RouteTemplate: "api/Users/Current/Profile", HttpVerb.Get)]
  public sealed partial class Query : IApiRequest, IRequest<OneOf<Response, SharedProblemDetails>>;

  public sealed class Validator : AbstractValidator<Query>;

  public sealed class Response : BaseResponse, IProfileDetails
  {
    public string Alias { get; set; }
    public string? Email { get; set; }
    public string Language { get; set; }
    public string Region { get; set; }
    public string Theme { get; set; }
    public bool Notifications { get; set; }
    public string Avatar { get; }

    public Response(
      string alias,
      string? email,
      string language,
      string region,
      string theme,
      bool notifications,
      string avatar)
    {
      Alias = Guard.Against.NullOrEmpty(alias);
      Email = string.IsNullOrWhiteSpace(email) ? null : email.Trim();
      Language = Guard.Against.NullOrEmpty(language);
      Region = Guard.Against.NullOrEmpty(region);
      Theme = Guard.Against.NullOrEmpty(theme);
      Notifications = notifications;
      Avatar = Guard.Against.NullOrEmpty(avatar);
    }
  }

  public static MockResponseFactory<Response> GetMockResponseFactory()
  {
    return _ => new Response(
      alias: "alias",
      email: null,
      language: "en-US",
      region: "US",
      theme: "system",
      notifications: false,
      avatar: "data:image/svg+xml;base64,");
  }
}
